import type { Tariff } from "../tariff/types.ts";
import { assertValidTariff } from "../tariff/validate.ts";
import { accumulate, chargeModeFor, EMPTY_ACCUMULATOR, type Accumulator } from "./accumulator.ts";
import { checkMeasurement, LIMITS, type Measurement, type MeasurementError } from "./measurement.ts";
import { DEFAULT_POLICY, type FarePolicy } from "./policy.ts";

/** An optional charge supplied by the caller (e.g. a toll). Never generated by the engine. */
export interface ExtraCharge {
  id: string; // unique per journey; re-adding the same id is rejected
  label: string;
  amountKurus: number;
}

export interface Journey {
  readonly tariff: Tariff; // fixed for the whole journey
  readonly policy: FarePolicy;
  readonly startedAtMs: number;
  readonly lastAtMs: number;
  readonly acc: Accumulator;
  readonly extras: readonly ExtraCharge[];
}

export type MeterState =
  | { readonly status: "SERBEST" }
  | { readonly status: "MESGUL"; readonly journey: Journey }
  | { readonly status: "UCRET"; readonly journey: Journey; readonly finalizedAtMs: number };

export type MeterCommand =
  | { type: "start"; tariff: Tariff; atMs: number; policy?: Partial<FarePolicy> }
  | { type: "measure"; measurement: Measurement }
  /** Unknown motion between the last measurement and atMs: baseline moves, nothing is charged. */
  | { type: "gap"; atMs: number }
  | { type: "finalize"; atMs: number }
  | { type: "resume"; atMs: number }
  | { type: "addCharge"; charge: ExtraCharge }
  | { type: "clear"; atMs: number };

export type MeterErrorCode =
  | "INVALID_TRANSITION"
  | "INVALID_TARIFF"
  | "INVALID_TIME"
  | "DISPLAY_TIME_NOT_ELAPSED"
  | "INVALID_CHARGE"
  | "DUPLICATE_CHARGE"
  | "JOURNEY_LIMIT"
  | MeasurementError;

export type MeterResult =
  | { ok: true; state: MeterState; error?: undefined }
  | { ok: false; state: MeterState; error: MeterErrorCode; message: string };

export const IDLE: MeterState = Object.freeze({ status: "SERBEST" });

const MAX_EXTRAS_KURUS = 10_000_000;

function fail(state: MeterState, error: MeterErrorCode, message: string): MeterResult {
  return { ok: false, state, error, message };
}

/**
 * Pure, deterministic meter transition. Never throws for bad input; a rejected command
 * returns the unchanged state plus an error code, so duplicate commands cannot double-charge.
 *
 * SERBEST --start--> MESGUL --finalize--> UCRET --clear (after display time)--> SERBEST
 *                                          UCRET --resume--> MESGUL
 */
export function transition(state: MeterState, cmd: MeterCommand): MeterResult {
  switch (cmd.type) {
    case "start": {
      if (state.status !== "SERBEST") return fail(state, "INVALID_TRANSITION", `start is only allowed in SERBEST, not ${state.status}`);
      if (!Number.isSafeInteger(cmd.atMs) || cmd.atMs < 0) return fail(state, "INVALID_TIME", "atMs must be a non-negative integer");
      try {
        assertValidTariff(cmd.tariff);
      } catch (err) {
        return fail(state, "INVALID_TARIFF", (err as Error).message);
      }
      const policy: FarePolicy = Object.freeze({ ...DEFAULT_POLICY, ...cmd.policy });
      if (!Number.isSafeInteger(policy.minFareDisplayMs) || policy.minFareDisplayMs < 0)
        return fail(state, "INVALID_TRANSITION", "policy.minFareDisplayMs must be a non-negative integer");
      const journey: Journey = {
        tariff: freezeTariff(cmd.tariff),
        policy,
        startedAtMs: cmd.atMs,
        lastAtMs: cmd.atMs,
        acc: EMPTY_ACCUMULATOR,
        extras: [],
      };
      return { ok: true, state: { status: "MESGUL", journey } };
    }

    case "measure": {
      if (state.status !== "MESGUL") return fail(state, "INVALID_TRANSITION", `measurements are only accepted in MESGUL, not ${state.status}`);
      const j = state.journey;
      const m = cmd.measurement;
      const err = checkMeasurement(m, j.lastAtMs);
      if (err) return fail(state, err, `rejected measurement: ${err}`);
      const dt = m.atMs - j.lastAtMs;
      if (j.acc.totalDurationMs + j.acc.unknownDurationMs + dt > LIMITS.maxJourneyMs || j.acc.totalDistanceMm + m.distanceMm > LIMITS.maxJourneyMm)
        return fail(state, "JOURNEY_LIMIT", "journey exceeds the supported duration or distance");
      const mode = chargeModeFor(m.speedKmh, j.tariff, j.policy);
      const acc = accumulate(j.acc, j.tariff, j.policy, dt, m.distanceMm, mode);
      return { ok: true, state: { status: "MESGUL", journey: { ...j, acc, lastAtMs: m.atMs } } };
    }

    case "gap": {
      if (state.status !== "MESGUL") return fail(state, "INVALID_TRANSITION", `gap is only accepted in MESGUL, not ${state.status}`);
      const j = state.journey;
      if (!Number.isSafeInteger(cmd.atMs) || cmd.atMs < j.lastAtMs) return fail(state, "INVALID_TIME", "gap end must be an integer ≥ the last measurement time");
      const dt = cmd.atMs - j.lastAtMs;
      if (dt === 0) return { ok: true, state };
      if (j.acc.totalDurationMs + j.acc.unknownDurationMs + dt > LIMITS.maxJourneyMs) return fail(state, "JOURNEY_LIMIT", "journey exceeds the supported duration");
      const acc = { ...j.acc, unknownDurationMs: j.acc.unknownDurationMs + dt, gapCount: j.acc.gapCount + 1 };
      return { ok: true, state: { status: "MESGUL", journey: { ...j, acc, lastAtMs: cmd.atMs } } };
    }

    case "finalize": {
      if (state.status !== "MESGUL") return fail(state, "INVALID_TRANSITION", `finalize is only allowed in MESGUL, not ${state.status}`);
      if (!Number.isSafeInteger(cmd.atMs) || cmd.atMs < state.journey.lastAtMs)
        return fail(state, "INVALID_TIME", "finalize time must be an integer ≥ the last measurement time");
      return { ok: true, state: { status: "UCRET", journey: state.journey, finalizedAtMs: cmd.atMs } };
    }

    case "resume": {
      if (state.status !== "UCRET") return fail(state, "INVALID_TRANSITION", `resume is only allowed in UCRET, not ${state.status}`);
      if (!Number.isSafeInteger(cmd.atMs) || cmd.atMs < state.finalizedAtMs)
        return fail(state, "INVALID_TIME", "resume time must be an integer ≥ the finalize time");
      // Time spent in UCRET is not charged: metering restarts from the resume instant.
      return { ok: true, state: { status: "MESGUL", journey: { ...state.journey, lastAtMs: cmd.atMs } } };
    }

    case "addCharge": {
      if (state.status === "SERBEST") return fail(state, "INVALID_TRANSITION", "charges can only be added to an active or finalized journey");
      const c = cmd.charge;
      if (typeof c?.id !== "string" || !c.id.trim() || typeof c.label !== "string" || !Number.isSafeInteger(c.amountKurus) || c.amountKurus <= 0)
        return fail(state, "INVALID_CHARGE", "charge needs a non-empty id, a label and a positive integer amountKurus");
      const j = state.journey;
      if (j.extras.some((e) => e.id === c.id)) return fail(state, "DUPLICATE_CHARGE", `charge ${c.id} was already added`);
      const total = j.extras.reduce((s, e) => s + e.amountKurus, 0) + c.amountKurus;
      if (total > MAX_EXTRAS_KURUS) return fail(state, "INVALID_CHARGE", "extra charges exceed the supported total");
      const journey = { ...j, extras: [...j.extras, Object.freeze({ ...c })] };
      return { ok: true, state: state.status === "MESGUL" ? { status: "MESGUL", journey } : { ...state, journey } };
    }

    case "clear": {
      if (state.status !== "UCRET") return fail(state, "INVALID_TRANSITION", `clear is only allowed in UCRET, not ${state.status}`);
      if (!Number.isSafeInteger(cmd.atMs) || cmd.atMs < state.finalizedAtMs) return fail(state, "INVALID_TIME", "clear time must be ≥ the finalize time");
      if (cmd.atMs - state.finalizedAtMs < state.journey.policy.minFareDisplayMs)
        return fail(state, "DISPLAY_TIME_NOT_ELAPSED", "the final fare must stay displayed for the minimum display time");
      return { ok: true, state: IDLE };
    }
  }
}

/** Snapshot so later edits to the caller's object cannot change an active journey's tariff. */
function freezeTariff(t: Tariff): Tariff {
  return Object.freeze({
    ...t,
    displayName: Object.freeze({ ...t.displayName }),
    reference: Object.freeze({ ...t.reference }),
    source: Object.freeze({ ...t.source }),
  });
}
